Predict the printed output of the C++ code:

class Base { public: virtual void print() { cout << "Base "; } };
class Derived : public Base { public: void print() override { cout << "Derived "; } };
int main() { Base* b = new Derived(); b->print(); Derived* d = (Derived*)b; d->print(); }

Predict the number of times 'Hello' is printed by this C program snippet:

#include <stdio.h>
#include <unistd.h>
int main() {
    fork();
    fork();
    printf("Hello\n");
    return 0;
}

